'use strict';
const assert = require('node:assert/strict');
const { createCache } = require('./src/cache');
const tick = () => new Promise(r => setImmediate(r));
const def = () => { let resolve, reject; const promise = new Promise((a, b) => { resolve = a; reject = b; }); return { promise, resolve, reject }; };

async function main() {
  // set during pending load: set wins, old completion doesn't overwrite or restart TTL
  {
    let t = 0; const g = def(); let calls = 0;
    const c = createCache({ now: () => t, ttlMs: 10, load: () => (++calls === 1 ? g.promise : 'new') });
    const r = c.get('k'); await tick();
    c.set('k', 'set'); t = 5; g.resolve('old');
    assert.equal(await r, 'old');
    assert.equal(await c.get('k'), 'set');
    t = 10; // set value expires at 10 even though old flight committed at 5
    assert.equal(c.size, 0);
    assert.equal(await c.get('k'), 'new'); assert.equal(calls, 2);
  }
  // repeated invalidations are separate barriers; old flight can't detach newer one
  {
    const gs = [def(), def(), def()]; let calls = 0;
    const c = createCache({ now: () => 0, load: () => gs[calls++].promise });
    const a = c.get('k'); c.invalidate('k');
    const b = c.get('k'); c.invalidate('k');
    const d = c.get('k'); await tick();
    gs[0].resolve('A'); gs[1].resolve('B'); await tick();
    const d2 = c.get('k'); // must join C
    gs[2].resolve('C');
    assert.deepEqual(await Promise.all([a, b, d, d2]), ['A', 'B', 'C', 'C']);
    assert.equal(calls, 3); assert.equal(await c.get('k'), 'C');
  }
  // clear detaches flights
  {
    const g = def(); let calls = 0;
    const c = createCache({ now: () => 0, load: () => (++calls === 1 ? g.promise : 'fresh') });
    const r = c.get('k'); await tick(); c.clear(); g.resolve('stale');
    assert.equal(await r, 'stale'); assert.equal(await c.get('k'), 'fresh'); assert.equal(c.size, 1);
  }
  // rejection: shared reason, not cached, retry works; sync throw; non-Error
  {
    let calls = 0; const reason = { nope: 1 };
    const c = createCache({ now: () => 0, load: () => { calls++; if (calls === 1) throw reason; if (calls === 2) return Promise.reject(7); return 'ok'; } });
    const [x, y] = [c.get('k'), c.get('k')];
    await assert.rejects(x, e => e === reason); await assert.rejects(y, e => e === reason);
    await assert.rejects(c.get('k'), e => e === 7);
    assert.equal(await c.get('k'), 'ok'); assert.equal(calls, 3);
  }
  // detached flight rejecting doesn't remove newer flight
  {
    const gs = [def(), def()]; let calls = 0;
    const c = createCache({ now: () => 0, load: () => gs[calls++].promise });
    const a = c.get('k'); await tick(); c.invalidate('k');
    const b = c.get('k'); await tick();
    gs[0].reject('boom'); await assert.rejects(a, e => e === 'boom');
    const b2 = c.get('k'); gs[1].resolve('B');
    assert.equal(await b, 'B'); assert.equal(await b2, 'B'); assert.equal(calls, 2);
  }
  // load mutating synchronously; load self-join
  {
    let c;
    c = createCache({ now: () => 0, load: k => { if (k === 'inv') { c.invalidate(k); return 'x'; } if (k === 'set') { c.set(k, 'S'); return 'L'; } c.get(k); return 'self'; } });
    assert.equal(await c.get('inv'), 'x'); assert.equal(c.size, 0);
    assert.equal(await c.get('set'), 'L'); assert.equal(await c.get('set'), 'S');
    assert.equal(await c.get('me'), 'self');
  }
  // TTL starts at commit; ttl 0 dedupes but never reuses
  {
    let t = 0; const g = def(); let calls = 0;
    const c = createCache({ now: () => t, ttlMs: 10, load: () => (++calls === 1 ? g.promise : 'n') });
    const r = c.get('k'); await tick(); t = 8; g.resolve('v'); await r;
    t = 17; assert.equal(await c.get('k'), 'v'); t = 18; assert.equal(await c.get('k'), 'n');
    let z = 0; const c0 = createCache({ now: () => 0, ttlMs: 0, load: async () => ++z });
    assert.deepEqual(await Promise.all([c0.get(1), c0.get(1)]), [1, 1]);
    assert.equal(await c0.get(1), 2); assert.equal(c0.size, 0);
  }
  console.log('all checks passed');
}
main().catch(e => { console.error(e); process.exit(1); });
